// GENERATED FILE -- DO NOT EDIT.
// Source: proxy/fonts/*.woff2 (regenerate those with scripts/fetch-fonts.py,
// then this with `node scripts/embed-fonts.mjs`). CI fails if it is stale.
//
// Decoded once at module scope: an isolate pays this on first use, not per
// request. Served from /fonts/<name> with a one-year immutable cache, so
// CHANGING A FONT MEANS CHANGING ITS FILENAME -- an immutable response that
// changes content is a cache nobody can clear.

const B64: Record<string, string> = {
  "grotesk.woff2": "",
  "inter.woff2": "",
  "mono.woff2": "",
};

function decode(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const FONTS: Record<string, Uint8Array> = Object.fromEntries(
  Object.entries(B64).map(([k, v]) => [k, decode(v)]),
);
